import {createStudy,canvasSurface,seededRandom,clamp,downloadCanvas} from './core.js';
const study=createStudy({id:8,title:'Word Weather',category:'Typography / Atmosphere',accent:'#f25929',background:'#9dbbff',foreground:'#101d47'});
const canvas=document.querySelector('#weather-canvas'),surface=canvasSurface(canvas,{maxDpr:1.5}),wordInput=document.querySelector('#weather-words');
let words=[],seed=8,wind=24,pointer={x:0,y:0,active:false,down:false},gather=false,lastW=0,lastH=0;
function forecast(){lastW=surface.width;lastH=surface.height;const w=surface.width,h=surface.height,ctx=surface.ctx,random=seededRandom(seed);const list=wordInput.value.toUpperCase().split(/[,\n]+/).map(w=>w.trim()).filter(Boolean).slice(0,8);if(!list.length)list.push('AIR');words=list.map((word,i)=>{const size=Math.min(w*.24,h*.18)*(word.length>6?.72:1)*(.72+random()*.35);ctx.font=`700 ${size}px Display, sans-serif`;const width=ctx.measureText(word).width;return{word,size,width,x:w*(.18+random()*.64),y:h*(.25+random()*.33),vx:(random()-.5)*40,vy:(random()-.5)*20,angle:(random()-.5)*.28,spin:(random()-.5)*.08,color:i%3===0?'#f25929':i%3===1?'#f6f0e1':'#101d47',phase:random()*6.28}})}
function draw({dt=0,time=0}={}){if(lastW!==surface.width||lastH!==surface.height)forecast();const {ctx,width:w,height:h}=surface;ctx.fillStyle='#9dbbff';ctx.fillRect(0,0,w,h);ctx.save();ctx.strokeStyle='#f6f0e14d';ctx.lineWidth=1;for(let i=0;i<6;i++){ctx.beginPath();ctx.ellipse(w*.5,h*.48,w*(.35+i*.15),h*(.11+i*.07),-.12,0,Math.PI*2);ctx.stroke()}ctx.restore();const step=study.running()?Math.min(dt,.032):0;for(const p of words){if(step){const targetX=(gather?w*.5:pointer.x),targetY=(gather?h*.45:pointer.y);const pull=(gather||pointer.down)?1.8:0;p.vx+=(wind*.65-p.vx)*step*.6+(targetX-p.x)*pull*step;p.vy+=(Math.sin(time*.6+p.phase)*15-p.vy)*step*.6+(targetY-p.y)*pull*step;if(pointer.active&&!pointer.down&&!gather){const dx=p.x-pointer.x,dy=p.y-pointer.y,d=Math.hypot(dx,dy)||1;if(d<150){p.vx+=dx/d*(150-d)*step*1.6;p.vy+=dy/d*(150-d)*step*1.6}}p.vx=clamp(p.vx,-170,170);p.vy=clamp(p.vy,-130,130);p.x+=p.vx*step;p.y+=p.vy*step;p.angle+=p.spin*step;if(p.x>w+p.width*.6)p.x=-p.width*.6;if(p.x<-p.width*.6)p.x=w+p.width*.6;p.y=clamp(p.y,170,h-200)}const edge=Math.min(1,(p.x+p.width*.6)/60,(w+p.width*.6-p.x)/60);ctx.save();ctx.globalAlpha=Math.max(.15,edge);ctx.translate(p.x,p.y);ctx.rotate(p.angle);ctx.font=`700 ${p.size}px Display, sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle=p.color;ctx.fillText(p.word,0,0);ctx.restore()}ctx.strokeStyle='#101d4750';ctx.setLineDash([2,7]);ctx.beginPath();ctx.moveTo(25,h*.73);ctx.lineTo(w-25,h*.73);ctx.stroke();ctx.setLineDash([]);ctx.font='8px Geist, sans-serif';ctx.fillStyle='#101d47';ctx.fillText('A VARIABLE ATMOSPHERE',28,h*.73+19)}
function locate(event){const r=canvas.getBoundingClientRect();pointer.x=event.clientX-r.left;pointer.y=event.clientY-r.top;pointer.active=true}
canvas.addEventListener('pointermove',locate);canvas.addEventListener('pointerdown',event=>{locate(event);pointer.down=true;canvas.setPointerCapture(event.pointerId)});for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,()=>pointer.down=false);canvas.addEventListener('pointerleave',()=>pointer.active=false);
wordInput.addEventListener('input',()=>{forecast();study.invalidate()});document.querySelector('#weather-wind').addEventListener('input',event=>{wind=Number(event.target.value);document.querySelector('#weather-wind-value').textContent=wind;document.querySelector('#weather-direction').textContent=`WIND ${wind<0?'←':'→'} ${Math.abs(wind)}`;study.invalidate()});
const gatherButton=document.querySelector('#weather-gather');gatherButton.addEventListener('pointerdown',event=>{gather=true;gatherButton.setPointerCapture(event.pointerId)});for(const type of ['pointerup','pointercancel','lostpointercapture'])gatherButton.addEventListener(type,()=>gather=false);gatherButton.addEventListener('keydown',event=>{if(event.key===' '||event.key==='Enter'){event.preventDefault();gather=true}});gatherButton.addEventListener('keyup',()=>gather=false);gatherButton.addEventListener('blur',()=>gather=false);
document.querySelector('#weather-change').addEventListener('click',()=>{seed++;forecast();study.invalidate()});study.onResize(()=>{surface.resize();forecast();study.invalidate()});study.onFrame(draw);study.setReset(()=>{wordInput.value='SLOW, FAST, SOFT, LOUD, AIR';seed=8;wind=24;gather=false;pointer={x:0,y:0,active:false,down:false};document.querySelector('#weather-wind').value='24';document.querySelector('#weather-wind-value').textContent='24';document.querySelector('#weather-direction').textContent='WIND → 24';forecast();study.invalidate()});study.setExport(()=>downloadCanvas(canvas,'08-word-weather.png'));study.cleanup(()=>surface.dispose());document.fonts.load('700 100px Display').then(()=>{forecast();study.invalidate()});
